    const add = (a, b) => ({ ...a, days: a.days + b.days, calendar: a.calendar + b.calendar, working: a.working + b.working, idle: a.idle + b.idle, breakdown: a.breakdown + b.breakdown, pending: a.pending + b.pending, fuel: a.fuel + b.fuel, workQty: a.workQty + b.workQty, logs: a.logs + b.logs, cost: a.cost + b.cost });
    const zero = { days: 0, calendar: 0, working: 0, idle: 0, breakdown: 0, pending: 0, fuel: 0, workQty: 0, logs: 0, cost: 0 }; const keyOf = (r) => (groupBy === 'class' ? `c${r.classItemId}` : groupBy === 'site' ? `s${r.siteId ?? 0}` : `e${r.equipmentId}`); const labelOf = (r) => (groupBy === 'class' ? r.class : groupBy === 'site' ? `${r.project}${r.site ? `/${r.site}` : ''}` : r.assetCode);
    const groups = new Map(); for (const r of rows) { const k = keyOf(r); const g = groups.get(k) ?? { key: k, label: labelOf(r), machines: 0, ...zero, classItemId: r.classItemId, siteId: r.siteId, projectId: r.projectId, equipmentId: r.equipmentId }; groups.set(k, { ...add(g, r), machines: g.machines + 1 }); }
